 async function complete(z){const before=await financial([z.id]),r=await mined(registry.recordPreparation(z.id,z.p));assert.equal((await registry.registration(z.id)).status,3n);assert.deepEqual(await financial([z.id]),before);const trace=await rpc.request({method:'debug_traceTransaction',params:[r.hash,{disableMemory:true,disableStack:true,disableStorage:true}]});assert(Array.isArray(trace.structLogs)&&trace.structLogs.length>0);const sstore=trace.structLogs.filter(x=>x.op==='SSTORE').length;assert(sstore>0);measurements.push({kind:'completePreparation',gas:String(r.gasUsed),sstore});return r;}
